window.AUTH=window.AUTH||{};window.AUTH["22-96"]={"d":"22-96","id":"2022/22-96","n":"Financial Oversight and Management Board for Puerto Rico v. Centro de Periodismo Investigativo, Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioner Financial Oversight and Management Board for Puerto Rico","date":"2022-11-17","url":"https://www.supremecourt.gov/DocketPDF/22/22-96/246883/20221117193815192_22-096%20Brief.pdf","side":"pet","n":66},{"k":"united-states","label":"Brief amicus curiae of United States supporting vacatur","date":"2022-11-23","url":"https://www.supremecourt.gov/DocketPDF/22/22-96/247434/20221123150006811_22-96%20FOMB%20v.%20CPI.pdf","side":"pet","n":77},{"k":"respondent","label":"Brief of respondent Centro de Periodismo Investigativo, Inc.","date":"2022-12-19","url":"https://www.supremecourt.gov/DocketPDF/22/22-96/250305/20221219131845710_Respondents%20Brief%20-%20FOMB%20v%20CPI.pdf","side":"res","n":67},{"k":"reply","label":"Reply of petitioner Financial Oversight and Management Board for Puerto Rico","date":"2023-01-03","url":"https://www.supremecourt.gov/DocketPDF/22/22-96/251227/20230103124000491_22-96_Petitioner%20Reply%20Brief.pdf","side":"pet","n":46}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us2r17_c0nd.pdf","tr":true,"items":[{"t":"case","label":"Alden v. Maine","cite":"527 U.S. 706","y":1999,"id":"1998/98-436","sc":1,"op":2,"sum":"A sharply divided court held in a 5-4 decision that Congress may not use its Article I powers to abrogate the states' sovereign immunity. Both the terms and history of the eleventh amendment suggest that States are immune from suits in their own courts.","sumSrc":"Oyez","by":{"0":"36","2":"18, 19, 28, 31","3":"4, 5, 6, 7"}},{"t":"case","label":"Allen v. Cooper","cite":"140 S. Ct. 994","y":2020,"id":"2019/18-877","sc":1,"sum":"The Court held that the Copyright Remedy Clarification Act was not a valid abrogation of state sovereign immunity to allow authors of original expression to sue states who infringe their federal copyrights.","sumSrc":"Oyez","by":{"0":"15, 22","2":"17, 18, 19, 24","3":"5"}},{"t":"case","label":"Atascadero State Hosp. v. Scanlon","cite":"473 U.S. 234","y":1985,"id":"1984/84-351","sc":1,"sum":"Respondent's action is proscribed by the Eleventh Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"27","3":"19"}},{"t":"case","label":"Bhatia Gautier v. Roselló Nevares","cite":"199 D.P.R. 59","y":2017,"court":"P.R.","url":"https://www.courtlistener.com/c/D.P.R./199/59/","by":{"0":"8","1":"7, 32"}},{"t":"case","label":"Blatchford v. Native Vill. of Noatak","cite":"501 U.S. 775","y":1991,"id":"1990/89-1782","sc":1,"op":1,"sum":"Respondents, Alaska Native villages, brought suit against petitioner, a state official, seeking an order requiring payment to them of money allegedly owed under a state revenue-sharing statute. The District Court dismissed the suit as violating the Eleventh Amendment. The Court of Appeals reversed, first on the ground that 28 U. S. C. § 1362 constituted a congressional abrogation of Eleventh Amendment immunity, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"27, 29","2":"24","3":"19"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"op":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Borrás-Borrero v. Corporación del Fondo del Seguro del Estado","cite":"958 F.3d 26","y":2020,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/958/26/","by":{"0":"9"}},{"t":"case","label":"Dellmuth v. Muth","cite":"491 U.S. 223","y":1989,"id":"1988/87-1855","sc":1,"op":2,"by":{"0":"passim","2":"20, 24, 26, 34","3":"15, 22"}},{"t":"case","label":"Diaz-Fonseca v. Puerto Rico","cite":"451 F.3d 13","y":2006,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/451/13/","by":{"0":"10"}},{"t":"case","label":"Emps. of Dep’t of Pub. Health & Welfare. v. Dep’t of Pub. Health & Welfare","cite":"411 U.S. 279","y":1973,"id":"1972/71-1021","sc":1,"sum":"Although amendments to the FLSA in 1966 extended statutory coverage to state employees, the legislative history discloses no congressional purpose to deprive a State of its constitutional immunity to suit in a federal forum by employees of its nonprofit institutions, particularly since Congress made no change in § 16 (b); which makes no reference to suits by employees against the State. Parden v. Terminal R. Co., …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Ezratty v. Puerto Rico","cite":"648 F.2d 770","y":1981,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/648/770/","by":{"0":"9","1":"15","2":"24"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"op":1,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"0":"29, 30, 40","1":"25, 26","2":"24, 34, 35","3":"13, 17"}},{"t":"case","label":"Facebook, Inc. v. Duguid","cite":"141 S. Ct. 1163","y":2021,"id":"2020/18-956","sc":1,"sum":"Google’s limited copying of the Java SE Application Programming Interface allowed programmers to put their accrued talents to work in a transformative program and constituted a fair use of that material under copyright law.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"27"}},{"t":"case","label":"Fin. Oversight & Mgmt. Bd. for P.R. v. Aurelius Inv., LLC","cite":"140 S. Ct. 1649","y":2020,"id":"2019/18-1334","sc":1,"sum":"A group of cases in which the Court will decide the constitutionality of President Barack Obama’s appointments (without their being confirmed by the Senate) to the oversight board created to help Puerto Rico recover from its substantial indebtedness.","sumSrc":"Oyez","by":{"0":"5, 6, 33","1":"5, 6, 12, 22, 23","2":"5, 6, 31","3":"8, 9, 10, 20"}},{"t":"case","label":"Fitzpatrick v. Bitzer","cite":"427 U.S. 445","y":1976,"id":"1975/75-251","sc":1,"op":1,"sum":"Present and retired male employees of the State of Connecticut (petitioners in No. 75-251) brought this class action alleging, inter alia, that certain provisions of the State's statutory retirement benefit plan discriminated against them because of their sex, in violation of Title VII of the Civil Rights Act of 1964, which, as amended, extends coverage to the States as employers. The District Court ruled in their …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 36","1":"20, 28"}},{"t":"case","label":"Guerrero-Lasprilla v. Barr","cite":"140 S. Ct. 1062","y":2020,"id":"2019/18-776","sc":1,"sum":"The Court held that the phrase “questions of law” in the Immigration and Nationality Act’s Limited Review Provision, 8 U. S. C. §1252(a)(2)(D), includes the application of a legal standard to undisputed or established facts.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Gundy v. United States","cite":"139 S. Ct. 2116","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"28"}},{"t":"case","label":"Kimel v. Fla. Bd. of Regents","cite":"528 U.S. 62","y":2000,"id":"1999/98-791","sc":1,"op":6,"sum":"The Court held that the ADEA contains a clear statement of Congress' intent to abrogate the states' immunity, but that the abrogation exceeds Congress' authority under the Fourteenth Amendment. \"States may discriminate on the basis of age without offending the Fourteenth Amendment if the age classification in question is rationally related to a legitimate state interest,\" wrote Justice O'Connor for the Court.","sumSrc":"Oyez","by":{"0":"15, 22, 29","1":"13, 25, 26","2":"passim","3":"15, 21"}},{"t":"case","label":"King v. Burwell","cite":"576 U.S. 473","y":2015,"id":"2014/14-114","sc":1,"sum":"The Court determined that the plain language of the Affordable Care Act extended tax credits to federally-created exchanges as well as those the states created.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Koons Buick Pontiac GMC, Inc. v. Nigh","cite":"543 U.S. 50","y":2004,"id":"2004/03-377","sc":1,"sum":"In an 8-1 judgment delivered by Justice Ruth Bader Ginsburg, the Court held that a 1995 TILA amendment did not change the original limit on violations involving personal-property loans. Congress intended the amendment to raise the minimum and maximum recoveries for closed-end loans secured by real property. Congress had not sought to remove the $1,000 cap on loans secured by personal property.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Lane v. Pena","cite":"518 U.S. 187","y":1996,"id":"1995/95-365","sc":1,"sum":"Although the related provisions of the 1973 Rehabilitation Act and the 1991 Civil Rights Act might in combination be read as waiving the federal government's sovereign immunity, absent an unambiguous waiver of sovereign immunity, the court cannot permit damages to be awarded.","sumSrc":"Oyez","by":{"0":"16, 28","1":"21","2":"24"}},{"t":"case","label":"Lindh v. Murphy","cite":"521 U.S. 320","y":1997,"id":"1996/96-6298","sc":1,"sum":"The Court held that the 1996 version of the federal habeas statute, as to standards affecting the entitlement of state prisoners to federal habeas corpus relief, does not to apply to non-capital habeas corpus cases that were pending when the Act was enacted.","sumSrc":"Oyez","by":{"0":"26","2":"38, 40","3":"21"}},{"t":"case","label":"Méndez-Núñez v. Fin. Oversight & Mgmt. Bd. for P.R. (In re Fin. Oversight & Mgmt. Bd. for P.R.)","cite":"916 F.3d 98","y":2019,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/916/98/","by":{"0":"34"}},{"t":"case","label":"Nev. Dep’t of Hum. Res. v. Hibbs","cite":"538 U.S. 721","y":2003,"id":"2002/01-1368","sc":1,"op":1,"sum":"The Court held that State employees may recover money damages in federal court in the event of the State's failure to comply with the FMLA's family-care provision.","sumSrc":"Oyez","by":{"0":"22, 25, 43","2":"34","3":"16"}},{"t":"case","label":"P.R. Aqueduct & Sewer Auth. v. Metcalf & Eddy, Inc.","cite":"506 U.S. 139","y":1993,"id":"1992/91-1010","sc":1,"op":1,"ar":1,"sum":"States and state entities that claim to be \"arms of the State\" may take advantage of the collateral order doctrine of Cohen v. Beneficial Industrial Loan Corp., 337 U. S. 541, to appeal a district court order denying a claim of Eleventh Amendment immunity from suit in federal court. Although 28 U. S. C. § 1291 requires that appeals be taken from \"final decisions of the district courts,\" Cohen, supra, at 546, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 10","1":"15","2":"12, 18"}},{"t":"case","label":"Pennhurst State Sch. & Hosp. v. Halderman","cite":"451 U.S. 1","y":1981,"id":"1980/79-1404","sc":1,"sum":"Section 6010 does not create in favor of the mentally retarded any substantive rights to \"appropriate treatment\" in the \"least restrictive\" environment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Pennhurst State Sch. & Hosp. v. Halderman","cite":"465 U.S. 89","y":1984,"id":"1982/81-2101","sc":1,"sum":"The Eleventh Amendment prohibited the District Court from ordering state officials to conform their conduct to state law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 10, 18, 43","1":"10, 16, 20","2":"20, 21, 22, 45","3":"7"}},{"t":"case","label":"Port Auth. Trans-Hudson Corp. v. Feeney","cite":"495 U.S. 299","y":1990,"id":"1989/89-386","sc":1,"sum":"The statutory consent to suit provision, as elucidated by the venue provision, establishes the States' waiver of any Eleventh Amendment immunity that might otherwise bar respondents' suits against PATH. It is appropriate here to assume, arguendo, that PATH is a state agency entitled to the States' sovereign immunity. Petty v. Tennessee-Missouri Bridge Comm'n, 359 U. S. 275, 279. In determining whether a State has …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20","1":"15"}},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Tr.","cite":"136 S. Ct. 1938","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"0":"6","1":"4"}},{"t":"case","label":"Quern v. Jordan","cite":"440 U.S. 332","y":1979,"id":"1978/77-841","sc":1,"sum":"In Edelman v. Jordan, 415 U. S. 651, it was held that retroactive welfare benefits awarded by a Federal District Court to the plaintiff class, by reason of wrongful denial of benefits by Illinois officials prior to the entry of the court's order determining the wrongfulness of their actions, violated the Eleventh Amendment, and that in an action under 42 U. S. C. § 1983 \"a federal court's remedial power, consistent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40, 42"}},{"t":"case","label":"Seminole Tribe of Fla. v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"op":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"0":"15, 25, 26, 43","1":"20, 26","2":"19, 24, 33, 34, 39, 40"}},{"t":"case","label":"Sossamon v. Texas","cite":"563 U.S. 277","y":2011,"id":"2010/08-1438","sc":1,"op":1,"sum":"The Court held that a person may not sue a state official in his individual capacity for damages under the Religious Land Use and Institutional Persons Act.","sumSrc":"Oyez","by":{"0":"passim","1":"26","2":"20"}},{"t":"case","label":"Spector v. Norwegian Cruise Line Ltd.","cite":"545 U.S. 119","y":2005,"id":"2004/03-1388","sc":1,"sum":"The Court held 6-3 that Title III applied to foreign-flag cruise ships in U.S. waters. Justice Kennedy delivered the Court's controlling opinion, which held that Title III did not apply to foreign ships' internal affairs, because there was no \"clear congressional statement\" showing an intent to do so. A clear statement was necessary before a general law could interfere with a foreign-vessel's internal affairs.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Thryv, Inc. v. Click-To-Call Techs., LP","cite":"140 S. Ct. 1367","y":2020,"id":"2019/18-916","sc":1,"sum":"The Court held that 35 U.S.C. §314(d) precludes judicial review of a Patent Trial and Appeal Board’s decision to institute inter partes review upon finding that §315(b)’s time bar did not apply.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Timmer v. Mich. Dep’t of Com.","cite":"104 F.3d 833","y":1997,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/104/833/","by":{"0":"25"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"United States v. Georgia","cite":"546 U.S. 151","y":2006,"id":"2005/04-1203","sc":1,"op":1,"sum":"The Court ruled that Title II abrogates sovereign immunity in cases where violations of the 8th Amendment are alleged. The 14th Amendment incorporates the 8th Amendment (that is, applies it to the states).","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"United States v. Laboy-Torres","cite":"553 F.3d 715","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/553/715/","by":{"0":"9"}},{"t":"case","label":"United States v. Nordic Vill., Inc.","cite":"503 U.S. 30","y":1992,"id":"1991/90-1629","sc":1,"sum":"After respondent Nordic Village, Inc., filed a petition for relief under Chapter 11 of the Bankruptcy Code, one of its officers withdrew funds from the company's corporate account. He sent part of the money to the Internal Revenue Service (IRS), directing it to apply the funds against his individual tax liability, which it did. In a subsequent adversary proceeding, the Bankruptcy Court permitted Nordic Village's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 29","1":"26","2":"24"}},{"t":"case","label":"Vázquez-Garced v. Fin. Oversight & Mgmt. Bd. for P.R. (In re Fin. Oversight & Mgmt. Bd. for P.R.)","cite":"945 F.3d 3","y":2019,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/945/3/","by":{"0":"25, 36","1":"28"}},{"t":"case","label":"West Virginia v. EPA","cite":"142 S. Ct. 2587","y":2022,"id":"2021/20-1530","sc":1,"sum":"Congress did not grant the Environmental Protection Agency in Section 111(d) of the Clean Air Act the authority to devise emissions caps based on the generation shifting approach the Agency took in the Clean Power Plan.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20","2":"26"}},{"t":"case","label":"Will v. Mich. Dep’t of State Police","cite":"491 U.S. 58","y":1989,"id":"1988/87-1207","sc":1,"op":1,"sum":"Neither States nor state officials acting in their official capacities are \"persons\" within meaning of § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"const","label":"Article IV, Section 3","clauses":[["property-clause","Territory and Property Clause"]],"text":"New States may be admitted by the Congress into this Union; but no new State shall be formed or erected within the Jurisdiction of any other State; nor any State be formed by the Junction of two or more States, or Parts of States, without the Consent of the Legislatures of the States concerned as well as of the Congress. The Congress shall have Power to dispose of and make all needful Rules and Regulations respecting the Territory or other Property belonging to the United States; and nothing in this Constitution shall be so construed as to Prejudice any Claims of the United States, or of any particular State.","by":{"0":"6"}},{"t":"usc","label":"5 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/5/552","subs":["(a)(3)(A)"],"by":{"0":"9"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(2)"],"by":{"0":"35"}},{"t":"usc","label":"25 U.S.C. § 2710","url":"https://www.law.cornell.edu/uscode/text/25/2710","subs":["(d)(7)","(d)(7)(A)(i)"],"stext":{"head":"§2710. Tribal gaming ordinances","paras":[[0,"(a) Jurisdiction over class I and class II gaming activity"],[0,"(1) Class I gaming on Indian lands is within the exclusive jurisdiction of the Indian tribes and shall not be subject to the provisions of this chapter."],[0,"(2) Any class II gaming on Indian lands shall continue to be within the jurisdiction of the Indian tribes, but shall be subject to the provisions of this chapter."],[0,"(b) Regulation of class II gaming activity; net revenue allocation; audits; contracts"],[0,"(1) An Indian tribe may engage in, or license and regulate, class II gaming on Indian lands within such tribe's jurisdiction, if—"],[1,"(A) such Indian gaming is located within a State that permits such gaming for any purpose by any person, organization or entity (and such gaming is not otherwise specifically prohibited on Indian lands by Federal law), and"],[1,"(B) the governing body of the Indian tribe adopts an ordinance or resolution which is approved by the Chairman."],[0,"A separate license issued by the Indian tribe shall be required for each place, facility, or location on Indian lands at which class II gaming is conducted."],[0,"(2) The Chairman shall approve any tribal ordinance or resolution concerning the conduct, or regulation of class II gaming on the Indian lands within the tribe's jurisdiction if such ordinance or resolution provides that—"],[1,"(A) except as provided in paragraph (4), the Indian tribe will have the sole proprietary interest and responsibility for the conduct of any gaming activity;"],[1,"(B) net revenues from any tribal gaming are not to be used for purposes other than—"],[2,"(i) to fund tribal government operations or programs;"],[2,"(ii) to provide for the general welfare of the Indian tribe and its members;"],[2,"(iii) to promote tribal economic development;"],[2,"(iv) to donate to charitable organizations; or"],[2,"(v) to help fund operations of local government agencies;"],[1,"(C) annual outside audits of the gaming, which may be encompassed within existing independent tribal audit systems, will be provided by the Indian tribe to the Commission;"],[1,"(D) all contracts for supplies, services, or concessions for a contract amount in excess of $25,000 annually (except contracts for professional legal or accounting services) relating to such gaming shall be subject to such independent audits;"],[1,"(E) the construction and maintenance of the gaming facility, and the operation of that gaming is conducted in a manner which adequately protects the environment and the public health and safety; and"],[1,"(F) there is an adequate system which—"],[2,"(i) ensures that background investigations are conducted on the primary management officials and key employees of the gaming enterprise and that oversight of such officials and their management is conducted on an ongoing basis; and"],[2,"(ii) includes—"],[3,"(I) tribal licenses for primary management officials and key employees of the gaming enterprise with prompt notification to the Commission of the issuance of such licenses;"],[3,"(II) a standard whereby any person whose prior activities, criminal record, if any, or reputation, habits and associations pose a threat to the public interest or to the effective regulation of gaming, or create or enhance the dangers of unsuitable, unfair, or illegal practices and methods and activities in the conduct of gaming shall not be eligible for employment; and"],[3,"(III) notification by the Indian tribe to the Commission of the results of such background check before the issuance of any of such licenses."],[0,"(3) Net revenues from any class II gaming activities conducted or licensed by any Indian tribe may be used to make per capita payments to members of the Indian tribe only if—"],[1,"(A) the Indian tribe has prepared a plan to allocate revenues to uses authorized by paragraph (2)(B);"],[1,"(B) the plan is approved by the Secretary as adequate, particularly with respect to uses described in clause (i) or (iii) of paragraph (2)(B);"],[1,"(C) the interests of minors and other legally incompetent persons who are entitled to receive any of the per capita payments are protected and preserved and the per capita payments are disbursed to the parents or legal guardian of such minors or legal incompetents in such amounts as may be necessary for the health, education, or welfare, of the minor or other legally incompetent person under a plan approved by the Secretary and the governing body of the Indian tribe; and"],[1,"(D) the per capita payments are subject to Federal taxation and tribes notify members of such tax liability when payments are made."],[0,"(4)(A) A tribal ordinance or resolution may provide for the licensing or regulation of class II gaming activities owned by any person or entity other than the Indian tribe and conducted on Indian lands, only if the tribal licensing requirements include the requirements described in the subclauses of subparagraph (B)(i) and are at least as restrictive as those established by State law governing similar gaming within the jurisdiction of the State within which such Indian lands are located. No person or entity, other than the Indian tribe, shall be eligible to receive a tribal license to own a class II gaming activity conducted on Indian lands within the jurisdiction of the Indian tribe if such person or entity would not be eligible to receive a State license to conduct the same activity within the jurisdiction of the State."],[0,"(B)(i) The provisions of subparagraph (A) of this paragraph and the provisions of subparagraphs (A) and (B) of paragraph (2) shall not bar the continued operation of an individually owned class II gaming operation that was operating on September 1, 1986, if—"],[1,"(I) such gaming operation is licensed and regulated by an Indian tribe pursuant to an ordinance reviewed and approved by the Commission in accordance with section 2712 of this title,"],[1,"(II) income to the Indian tribe from such gaming is used only for the purposes described in paragraph (2)(B) of this subsection,"],[1,"(III) not less than 60 percent of the net revenues is income to the Indian tribe, and"],[1,"(IV) the owner of such gaming operation pays an appropriate assessment to the National Indian Gaming Commission under section 2717(a)(1) of this title for regulation of such gaming."],[0,"(ii) The exemption from the application of this subsection provided under this subparagraph may not be transferred to any person or entity and shall remain in effect only so long as the gaming activity remains within the same nature and scope as operated on October 17, 1988."],[0,"(iii) Within sixty days of October 17, 1988, the Secretary shall prepare a list of each individually owned gaming operation to which clause (i) applies and shall publish such list in the Federal Register."],[0,"(c) Issuance of gaming license; certificate of self-regulation"],[0,"(1) The Commission may consult with appropriate law enforcement officials concerning gaming licenses issued by an Indian tribe and shall have thirty days to notify the Indian tribe of any objections to issuance of such license."],[0,"(2) If, after the issuance of a gaming license by an Indian tribe, reliable information is received from the Commission indicating that a primary management official or key employee does not meet the standard established under subsection (b)(2)(F)(ii)(II), the Indian tribe shall suspend such license and, after notice and hearing, may revoke such license."],[0,"(3) Any Indian tribe which operates a class II gaming activity and which—"],[1,"(A) has continuously conducted such activity for a period of not less than three years, including at least one year after October 17, 1988; and"],[1,"(B) has otherwise complied with the provisions of this section 1"],[0,"may petition the Commission for a certificate of self-regulation."],[0,"(4) The Commission shall issue a certificate of self-regulation if it determines from available information, and after a hearing if requested by the tribe, that the tribe has—"],[1,"(A) conducted its gaming activity in a manner which—"],[2,"(i) has resulted in an effective and honest accounting of all revenues;"],[2,"(ii) has resulted in a reputation for safe, fair, and honest operation of the activity; and"],[2,"(iii) has been generally free of evidence of criminal or dishonest activity;"],[1,"(B) adopted and is implementing adequate systems for—"],[2,"(i) accounting for all revenues from the activity;"],[2,"(ii) investigation, licensing, and monitoring of all employees of the gaming activity; and"],[2,"(iii) investigation, enforcement and prosecution of violations of its gaming ordinance and regulations; and"],[1,"(C) conducted the operation on a fiscally and economically sound basis."],[0,"(5) During any year in which a tribe has a certificate for self-regulation—"],[1,"(A) the tribe shall not be subject to the provisions of paragraphs (1), (2), (3), and (4) of section 2706(b) of this title;"],[1,"(B) the tribe shall continue to submit an annual independent audit as required by subsection (b)(2)(C) and shall submit to the Commission a complete resume on all employees hired and licensed by the tribe subsequent to the issuance of a certificate of self-regulation; and"],[1,"(C) the Commission may not assess a fee on such activity pursuant to section 2717 of this title in excess of one quarter of 1 per centum of the gross revenue."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/2710?type=usc&year=mostrecent&link-type=html"},"head":"§2710. Tribal gaming ordinances","tname":"Indians","by":{"0":"25, 26","1":"26"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"4"}},{"t":"usc","label":"28 U.S.C. § 1334","url":"https://www.law.cornell.edu/uscode/text/28/1334","by":{"0":"17, 24, 33"}},{"t":"usc","label":"28 U.S.C. § 1362","url":"https://www.law.cornell.edu/uscode/text/28/1362","by":{"0":"23"}},{"t":"usc","label":"35 U.S.C. § 314","url":"https://www.law.cornell.edu/uscode/text/35/314","subs":["(d)"],"by":{"0":"34"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"0":"42"}},{"t":"usc","label":"48 U.S.C. § 2103","url":"https://www.law.cornell.edu/uscode/text/48/2103","by":{"0":"7, 42"}},{"t":"usc","label":"48 U.S.C. § 2121","url":"https://www.law.cornell.edu/uscode/text/48/2121","subs":["(a)","(b)","(b)(1)","(b)(2)","(c)","(c)(1)","(e)"],"stext":{"head":"§2121. Financial Oversight and Management Board","paras":[[0,"(a) Purpose"],[0,"The purpose of the Oversight Board is to provide a method for a covered territory to achieve fiscal responsibility and access to the capital markets."],[0,"(b) Establishment"],[0,"(1) Puerto Rico"],[1,"A Financial Oversight and Management Board is hereby established for Puerto Rico."],[0,"(2) Constitutional basis"],[1,"The Congress enacts this chapter pursuant to article IV, section 3 of the Constitution of the United States, which provides Congress the power to dispose of and make all needful rules and regulations for territories."],[0,"(c) Treatment"],[0,"An Oversight Board established under this section—"],[1,"(1) shall be created as an entity within the territorial government for which it is established in accordance with this subchapter; and"],[1,"(2) shall not be considered to be a department, agency, establishment, or instrumentality of the Federal Government."],[0,"(d) Oversight of territorial instrumentalities"],[0,"(1) Designation"],[0,"(A) In general"],[2,"An Oversight Board, in its sole discretion at such time as the Oversight Board determines to be appropriate, may designate any territorial instrumentality as a covered territorial instrumentality that is subject to the requirements of this chapter."],[0,"(B) Budgets and reports"],[2,"The Oversight Board may require, in its sole discretion, the Governor to submit to the Oversight Board such budgets and monthly or quarterly reports regarding a covered territorial instrumentality as the Oversight Board determines to be necessary and may designate any covered territorial instrumentality to be included in the Territory Budget; except that the Oversight Board may not designate a covered territorial instrumentality to be included in the Territory Budget if applicable territory law does not require legislative approval of such covered territorial instrumentality's budget."],[0,"(C) Separate Instrumentality Budgets and reports"],[2,"The Oversight Board in its sole discretion may or, if it requires a budget from a covered territorial instrumentality whose budget does not require legislative approval under applicable territory law, shall designate a covered territorial instrumentality to be the subject of an Instrumentality Budget separate from the applicable Territory Budget and require that the Governor develop such an Instrumentality Budget."],[0,"(D) Inclusion in Territory Fiscal Plan"],[2,"The Oversight Board may require, in its sole discretion, the Governor to include a covered territorial instrumentality in the applicable Territory Fiscal Plan. Any covered territorial instrumentality submitting a separate Instrumentality Fiscal Plan must also submit a separate Instrumentality Budget."],[0,"(E) Separate Instrumentality Fiscal Plans"],[2,"The Oversight Board may designate, in its sole discretion, a covered territorial instrumentality to be the subject of an Instrumentality Fiscal Plan separate from the applicable Territory Fiscal Plan and require that the Governor develop such an Instrumentality Fiscal Plan. Any covered territorial instrumentality submitting a separate Instrumentality Fiscal Plan shall also submit a separate Instrumentality Budget."],[0,"(2) Exclusion"],[0,"(A) In general"],[2,"An Oversight Board, in its sole discretion, at such time as the Oversight Board determines to be appropriate, may exclude any territorial instrumentality from the requirements of this chapter."],[0,"(B) Treatment"],[2,"A territorial instrumentality excluded pursuant to this paragraph shall not be considered to be a covered territorial instrumentality."],[0,"(e) Membership"],[0,"(1) In general"],[1,"(A) The Oversight Board shall consist of seven members appointed by the President who meet the qualifications described in subsection (f) and section 2129(a) of this title."],[1,"(B) The Board shall be comprised of one Category A member, one Category B member, two Category C members, one Category D member, one Category E member, and one Category F member."],[0,"(2) Appointed members"],[1,"(A) The President shall appoint the individual members of the Oversight Board, of which—"],[2,"(i) the Category A member should be selected from a list of individuals submitted by the Speaker of the House of Representatives;"],[2,"(ii) the Category B member should be selected from a separate, non-overlapping list of individuals submitted by the Speaker of the House of Representatives;"],[2,"(iii) the Category C members should be selected from a list submitted by the Majority Leader of the Senate;"],[2,"(iv) the Category D member should be selected from a list submitted by the Minority Leader of the House of Representatives;"],[2,"(v) the Category E member should be selected from a list submitted by the Minority Leader of the Senate; and"],[2,"(vi) the Category F member may be selected in the President's sole discretion."],[1,"(B) After the President's selection of the Category F Board member, for purposes of subparagraph (A) and within a timely manner—"],[2,"(i) the Speaker of the House of Representatives shall submit two non-overlapping lists of at least three individuals to the President; one list shall include three individuals who maintain a primary residence in the territory or have a primary place of business in the territory;"],[2,"(ii) the Senate Majority Leader shall submit a list of at least four individuals to the President;"],[2,"(iii) the Minority Leader of the House of Representatives shall submit a list of at least three individuals to the President; and"],[2,"(iv) the Minority Leader of the Senate shall submit a list of at least three individuals to the President."],[1,"(C) If the President does not select any of the names submitted under subparagraphs (A) and (B), then whoever submitted such list may supplement the lists provided in this subsection with additional names."],[1,"(D) The Category A member shall maintain a primary residence in the territory or have a primary place of business in the territory."],[1,"(E) With respect to the appointment of a Board member in Category A, B, C, D, or E, such an appointment shall be by and with the advice and consent of the Senate, unless the President appoints an individual from a list, as provided in this subsection, in which case no Senate confirmation is required."],[1,"(F) In the event of a vacancy of a Category A, B, C, D, or E Board seat, the corresponding congressional leader referenced in subparagraph (A) shall submit a list pursuant to this subsection within a timely manner of the Board member's resignation or removal becoming effective."],[1,"(G) With respect to an Oversight Board for Puerto Rico, in the event any of the 7 members have not been appointed by September 1, 2016, then the President shall appoint an individual from the list for the current vacant category by September 15, 2016, provided that such list includes at least 2 individuals per vacancy who meet the requirements set forth in subsection (f) and section 2129 of this title, and are willing to serve."],[0,"(3) Ex officio member"],[1,"The Governor, or the Governor's designee, shall be an ex officio member of the Oversight Board without voting rights."],[0,"(4) Chair"],[1,"The voting members of the Oversight Board shall designate one of the voting members of the Oversight Board as the Chair of the Oversight Board (referred to hereafter in this chapter as the \"Chair\") within 30 days of the full appointment of the Oversight Board."],[0,"(5) Term of service"],[0,"(A) In general"],[2,"Each appointed member of the Oversight Board shall be appointed for a term of 3 years."],[0,"(B) Removal"],[2,"The President may remove any member of the Oversight Board only for cause."],[0,"(C) Continuation of service until successor appointed"],[2,"Upon the expiration of a term of office, a member of the Oversight Board may continue to serve until a successor has been appointed."],[0,"(D) Reappointment"],[2,"An individual may serve consecutive terms as an appointed member, provided that such reappointment occurs in compliance with paragraph (6)."],[0,"(6) Vacancies"],[1,"A vacancy on the Oversight Board shall be filled in the same manner in which the original member was appointed."],[0,"(f) Eligibility for appointments"],[0,"An individual is eligible for appointment as a member of the Oversight Board only if the individual—"],[1,"(1) has knowledge and expertise in finance, municipal bond markets, management, law, or the organization or operation of business or government; and"],[1,"(2) prior to appointment, an individual is not an officer, elected official, or employee of the territorial government, a candidate for elected office of the territorial government, or a former elected official of the territorial government."],[0,"(g) No compensation for service"],[0,"Members of the Oversight Board shall serve without pay, but may receive reimbursement from the Oversight Board for any reasonable and necessary expenses incurred by reason of service on the Oversight Board."],[0,"(h) Adoption of bylaws for conducting business of Oversight Board"],[0,"(1) In general"],[1,"As soon as practicable after the appointment of all members and appointment of the Chair, the Oversight Board shall adopt bylaws, rules, and procedures governing its activities under this chapter, including procedures for hiring experts and consultants. Such bylaws, rules, and procedures shall be public documents, and shall be submitted by the Oversight Board upon adoption to the Governor, the Legislature, the President, and Congress. The Oversight Board may hire professionals as it determines to be necessary to carry out this chapter."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/48/2121?type=usc&year=mostrecent&link-type=html"},"head":"§2121. Financial Oversight and Management Board","tname":"Territories and Insular Possessions","by":{"0":"passim","1":"4, 23, 5, 4, 22, 23, 29, 12, 5"}},{"t":"usc","label":"48 U.S.C. § 2124","url":"https://www.law.cornell.edu/uscode/text/48/2124","stext":{"head":"§2124. Powers of Oversight Board","paras":[[0,"(a) Hearings and sessions"],[0,"The Oversight Board may, for the purpose of carrying out this chapter, hold hearings, sit and act at times and places, take testimony, and receive evidence as the Oversight Board considers appropriate. The Oversight Board may administer oaths or affirmations to witnesses appearing before it."],[0,"(b) Powers of members and agents"],[0,"Any member or agent of the Oversight Board may, if authorized by the Oversight Board, take any action that the Oversight Board is authorized to take by this section."],[0,"(c) Obtaining official data"],[0,"(1) From Federal government"],[1,"Notwithstanding sections 552 (commonly known as the Freedom of Information Act), 552a (commonly known as the Privacy Act of 1974), and 552b (commonly known as the Government in the Sunshine Act) of title 5, the Oversight Board may secure directly from any department or agency of the United States information necessary to enable it to carry out this chapter, with the approval of the head of that department or agency."],[0,"(2) From territorial government"],[1,"Notwithstanding any other provision of law, the Oversight Board shall have the right to secure copies, whether written or electronic, of such records, documents, information, data, or metadata from the territorial government necessary to enable the Oversight Board to carry out its responsibilities under this chapter. At the request of the Oversight Board, the Oversight Board shall be granted direct access to such information systems, records, documents, information, or data as will enable the Oversight Board to carry out its responsibilities under this chapter. The head of the entity of the territorial government responsible shall provide the Oversight Board with such information and assistance (including granting the Oversight Board direct access to automated or other information systems) as the Oversight Board requires under this paragraph."],[0,"(d) Obtaining creditor information"],[0,"(1) Upon request of the Oversight Board, each creditor or organized group of creditors of a covered territory or covered territorial instrumentality seeking to participate in voluntary negotiations shall provide to the Oversight Board, and the Oversight Board shall make publicly available to any other participant, a statement setting forth—"],[1,"(A) the name and address of the creditor or of each member of an organized group of creditors; and"],[1,"(B) the nature and aggregate amount of claims or other economic interests held in relation to the issuer as of the later of—"],[2,"(i) the date the creditor acquired the claims or other economic interests or, in the case of an organized group of creditors, the date the group was formed; or"],[2,"(ii) the date the Oversight Board was formed."],[1,"(2) For purposes of this subsection, an organized group shall mean multiple creditors that are—"],[2,"(A) acting in concert to advance their common interests, including, but not limited to, retaining legal counsel to represent such multiple entities; and"],[2,"(B) not composed entirely of affiliates or insiders of one another."],[1,"(3) The Oversight Board may request supplemental statements to be filed by each creditor or organized group of creditors quarterly, or if any fact in the most recently filed statement has changed materially."],[0,"(e) Gifts, bequests, and devises"],[0,"The Oversight Board may accept, use, and dispose of gifts, bequests, or devises of services or property, both real and personal, for the purpose of aiding or facilitating the work of the Oversight Board. Gifts, bequests, or devises of money and proceeds from sales of other property received as gifts, bequests, or devises shall be deposited in such account as the Oversight Board may establish and shall be available for disbursement upon order of the Chair, consistent with the Oversight Board's bylaws, or rules and procedures. All gifts, bequests or devises and the identities of the donors shall be publicly disclosed by the Oversight Board within 30 days of receipt."],[0,"(f) Subpoena power"],[0,"(1) In general"],[1,"The Oversight Board may issue subpoenas requiring the attendance and testimony of witnesses and the production of books, records, correspondence, memoranda, papers, documents, electronic files, metadata, tapes, and materials of any nature relating to any matter under investigation by the Oversight Board. Jurisdiction to compel the attendance of witnesses and the production of such materials shall be governed by the statute setting forth the scope of personal jurisdiction exercised by the covered territory, or in the case of Puerto Rico, 32 L.P.R.A. App. III. R. 4. 7., as amended."],[0,"(2) Failure to obey a subpoena"],[1,"If a person refuses to obey a subpoena issued under paragraph (1), the Oversight Board may apply to the court of first instance of the covered territory. Any failure to obey the order of the court may be punished by the court in accordance with civil contempt laws of the covered territory."],[0,"(3) Service of subpoenas"],[1,"The subpoena of the Oversight Board shall be served in the manner provided by the rules of procedure for the courts of the covered territory, or in the case of Puerto Rico, the Rules of Civil Procedure of Puerto Rico, for subpoenas issued by the court of first instance of the covered territory."],[0,"(g) Authority to enter into contracts"],[0,"The Executive Director may enter into such contracts as the Executive Director considers appropriate (subject to the approval of the Chair) consistent with the Oversight Board's bylaws, rules, and regulations to carry out the Oversight Board's responsibilities under this chapter."],[0,"(h) Authority to enforce certain laws of the covered territory"],[0,"The Oversight Board shall ensure the purposes of this chapter are met, including by ensuring the prompt enforcement of any applicable laws of the covered territory prohibiting public sector employees from participating in a strike or lockout. In the application of this subsection, with respect to Puerto Rico, the term \"applicable laws\" refers to 3 L.P.R.A. 1451q and 3 L.P.R.A. 1451r, as amended."],[0,"(i) Voluntary agreement certification"],[0,"(1) In general"],[1,"The Oversight Board shall issue a certification to a covered territory or covered territorial instrumentality if the Oversight Board determines, in its sole discretion, that such covered territory or covered territorial instrumentality, as applicable, has successfully reached a voluntary agreement with holders of its Bond Claims to restructure such Bond Claims—"],[2,"(A) except as provided in subparagraph (C), if an applicable Fiscal Plan has been certified, in a manner that provides for a sustainable level of debt for such covered territory or covered territorial instrumentality, as applicable, and is in conformance with the applicable certified Fiscal Plan;"],[2,"(B) except as provided in subparagraph (C), if an applicable Fiscal Plan has not yet been certified, in a manner that provides, in the Oversight Board's sole discretion, for a sustainable level of debt for such covered territory or covered territorial instrumentality; or"],[2,"(C) notwithstanding subparagraphs (A) and (B), if an applicable Fiscal Plan has not yet been certified and the voluntary agreement is limited solely to an extension of applicable principal maturities and interest on Bonds issued by such covered territory or covered territorial instrumentality, as applicable, for a period of up to one year during which time no interest will be paid on the Bond Claims affected by the voluntary agreement."],[0,"(2) Effectiveness"],[1,"The effectiveness of any voluntary agreement referred to in paragraph (1) shall be conditioned on—"],[2,"(A) the Oversight Board delivering the certification described in paragraph (1); and"],[2,"(B) the agreement of a majority in amount of the Bond Claims of a covered territory or a covered territorial instrumentality that are to be affected by such agreement, provided, however, that such agreement is solely for purposes of serving as a Qualifying Modification pursuant to subsection 1 2231(g) of this title and shall not alter existing legal rights of holders of Bond Claims against such covered territory or covered territorial instrumentality that have not assented to such agreement until an order approving the Qualifying Modification has been entered pursuant to section 2231(m)(1)(D) of this title."],[0,"(3) Preexisting voluntary agreements"],[1,"Any voluntary agreement that the territorial government or any territorial instrumentality has executed before May 18, 2016, with holders of a majority in amount of Bond Claims that are to be affected by such agreement to restructure such Bond Claims shall be deemed to be in conformance with the requirements of this subsection."],[0,"(j) Restructuring filings"],[0,"(1) In general"],[1,"Subject to paragraph (3), before taking an action described in paragraph (2) on behalf of a debtor or potential debtor in a case under subchapter III, the Oversight Board must certify the action."],[0,"(2) Actions described"],[1,"The actions referred to in paragraph (1) are—"],[2,"(A) the filing of a petition; or"],[2,"(B) the submission or modification of a plan of adjustment."],[0,"(3) Condition for plans of adjustment"],[1,"The Oversight Board may certify a plan of adjustment only if it determines, in its sole discretion, that it is consistent with the applicable certified Fiscal Plan."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/48/2124?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2124. Powers of Oversight Board","tname":"Territories and Insular Possessions","by":{"0":"passim"}},{"t":"usc","label":"48 U.S.C. § 2125","url":"https://www.law.cornell.edu/uscode/text/48/2125","stext":{"head":"§2125. Exemption from liability for claims","paras":[[0,"The Oversight Board, its members, and its employees shall not be liable for any obligation of or claim against the Oversight Board or its members or employees or the territorial government resulting from actions taken to carry out this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/48/2125?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§2125. Exemption from liability for claims","tname":"Territories and Insular Possessions","by":{"0":"7, 41","1":"14, 30","3":"18, 21, 22"}},{"t":"usc","label":"48 U.S.C. § 2126","url":"https://www.law.cornell.edu/uscode/text/48/2126","subs":["(a)","(c)"],"stext":{"head":"§2126. Treatment of actions arising from chapter","paras":[[0,"(a) Jurisdiction"],[0,"Except as provided in section 2124(f)(2) of this title (relating to the issuance of an order enforcing a subpoena), and subchapter III (relating to adjustments of debts), any action against the Oversight Board, and any action otherwise arising out of this chapter, in whole or in part, shall be brought in a United States district court for the covered territory or, for any covered territory that does not have a district court, in the United States District Court for the District of Hawaii."],[0,"(b) Appeal"],[0,"Notwithstanding any other provision of law, any order of a United States district court that is issued pursuant to an action brought under subsection (a) shall be subject to review only pursuant to a notice of appeal to the applicable United States Court of Appeals."],[0,"(c) Timing of relief"],[0,"Except with respect to any orders entered to remedy constitutional violations, no order of any court granting declaratory or injunctive relief against the Oversight Board, including relief permitting or requiring the obligation, borrowing, or expenditure of funds, shall take effect during the pendency of the action before such court, during the time appeal may be taken, or (if appeal is taken) during the period before the court has entered its final order disposing of such action."],[0,"(d) Expedited consideration"],[0,"It shall be the duty of the applicable United States District Court, the applicable United States Court of Appeals, and, as applicable, the Supreme Court of the United States to advance on the docket and to expedite to the greatest possible extent the disposition of any matter brought under this chapter."],[0,"(e) Review of Oversight Board certifications"],[0,"There shall be no jurisdiction in any United States district court to review challenges to the Oversight Board's certification determinations under this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/48/2126?type=usc&year=mostrecent&link-type=html"},"head":"§2126. Treatment of actions arising from chapter","tname":"Territories and Insular Possessions","by":{"0":"passim","1":"5, 6, 27, 6","3":"passim"}},{"t":"usc","label":"48 U.S.C. § 2127","url":"https://www.law.cornell.edu/uscode/text/48/2127","subs":["(b)"],"stext":{"head":"§2127. Budget and funding for operation of Oversight Board","paras":[[0,"(a) Submission of budget"],[0,"The Oversight Board shall submit a budget for each fiscal year during which the Oversight Board is in operation, to the President, the House of Representatives Committee on Natural Resources and the Senate Committee on Energy and Natural Resources, the Governor, and the Legislature."],[0,"(b) Funding"],[0,"The Oversight Board shall use its powers with respect to the Territory Budget of the covered territory to ensure that sufficient funds are available to cover all expenses of the Oversight Board."],[0,"(1) Permanent funding"],[1,"Within 30 days after June 30, 2016, the territorial government shall designate a dedicated funding source, not subject to subsequent legislative appropriations, sufficient to support the annual expenses of the Oversight Board as determined in the Oversight Board's sole and exclusive discretion."],[0,"(2)(A) Initial funding"],[1,"On the date of establishment of an Oversight Board in accordance with section 2121(b) of this title and on the 5th day of each month thereafter, the Governor of the covered territory shall transfer or cause to be transferred the greater of $2,000,000 or such amount as shall be determined by the Oversight Board pursuant to subsection (a) to a new account established by the territorial government, which shall be available to and subject to the exclusive control of the Oversight Board, without any legislative appropriations of the territorial government."],[0,"(B) Termination"],[1,"The initial funding requirements under subparagraph (A) shall terminate upon the territorial government designating a dedicated funding source not subject to subsequent legislative appropriations under paragraph (1)."],[0,"(3) Remission of excess funds"],[1,"If the Oversight Board determines in its sole discretion that any funds transferred under this subsection exceed the amounts required for the Oversight Board's operations as established pursuant to subsection (a), any such excess funds shall be periodically remitted to the territorial government."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/48/2127?type=usc&year=mostrecent&link-type=html"},"head":"§2127. Budget and funding for operation of Oversight Board","tname":"Territories and Insular Possessions","by":{"0":"6","1":"23"}},{"t":"usc","label":"48 U.S.C. § 2128","url":"https://www.law.cornell.edu/uscode/text/48/2128","subs":["(a)(2)"],"stext":{"head":"§2128. Autonomy of Oversight Board","paras":[[0,"(a) In general"],[0,"Neither the Governor nor the Legislature may—"],[1,"(1) exercise any control, supervision, oversight, or review over the Oversight Board or its activities; or"],[1,"(2) enact, implement, or enforce any statute, resolution, policy, or rule that would impair or defeat the purposes of this chapter, as determined by the Oversight Board."],[0,"(b) Oversight Board legal representation"],[0,"In any action brought by, on behalf of, or against the Oversight Board, the Oversight Board shall be represented by such counsel as it may hire or retain so long as the representation complies with the applicable professional rules of conduct governing conflicts of interests."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/48/2128?type=usc&year=mostrecent&link-type=html"},"head":"§2128. Autonomy of Oversight Board","tname":"Territories and Insular Possessions","by":{"0":"7, 42","1":"33, 14, 29"}},{"t":"usc","label":"48 U.S.C. § 2141","url":"https://www.law.cornell.edu/uscode/text/48/2141","stext":{"head":"§2141. Approval of Fiscal Plans","paras":[[0,"(a) In general"],[0,"As soon as practicable after all of the members and the Chair have been appointed to the Oversight Board in accordance with section 2121(e) of this title in the fiscal year in which the Oversight Board is established, and in each fiscal year thereafter during which the Oversight Board is in operation, the Oversight Board shall deliver a notice to the Governor providing a schedule for the process of development, submission, approval, and certification of Fiscal Plans. The notice may also set forth a schedule for revisions to any Fiscal Plan that has already been certified, which revisions must be subject to subsequent approval and certification by the Oversight Board. The Oversight Board shall consult with the Governor in establishing a schedule, but the Oversight Board shall retain sole discretion to set or, by delivery of a subsequent notice to the Governor, change the dates of such schedule as it deems appropriate and reasonably feasible."],[0,"(b) Requirements"],[0,"(1) In general"],[1,"A Fiscal Plan developed under this section shall, with respect to the territorial government or covered territorial instrumentality, provide a method to achieve fiscal responsibility and access to the capital markets, and—"],[2,"(A) provide for estimates of revenues and expenditures in conformance with agreed accounting standards and be based on—"],[3,"(i) applicable laws; or"],[3,"(ii) specific bills that require enactment in order to reasonably achieve the projections of the Fiscal Plan;"],[2,"(B) ensure the funding of essential public services;"],[2,"(C) provide adequate funding for public pension systems;"],[2,"(D) provide for the elimination of structural deficits;"],[2,"(E) for fiscal years covered by a Fiscal Plan in which a stay under subchapters III or IV is not effective, provide for a debt burden that is sustainable;"],[2,"(F) improve fiscal governance, accountability, and internal controls;"],[2,"(G) enable the achievement of fiscal targets;"],[2,"(H) create independent forecasts of revenue for the period covered by the Fiscal Plan;"],[2,"(I) include a debt sustainability analysis;"],[2,"(J) provide for capital expenditures and investments necessary to promote economic growth;"],[2,"(K) adopt appropriate recommendations submitted by the Oversight Board under section 2145(a) of this title;"],[2,"(L) include such additional information as the Oversight Board deems necessary;"],[2,"(M) ensure that assets, funds, or resources of a territorial instrumentality are not loaned to, transferred to, or otherwise used for the benefit of a covered territory or another covered territorial instrumentality of a covered territory, unless permitted by the constitution of the territory, an approved plan of adjustment under subchapter III, or a Qualifying Modification approved under subchater VI; and"],[2,"(N) respect the relative lawful priorities or lawful liens, as may be applicable, in the constitution, other laws, or agreements of a covered territory or covered territorial instrumentality in effect prior to June 30, 2016."],[0,"(2) Term"],[1,"A Fiscal Plan developed under this section shall cover a period of fiscal years as determined by the Oversight Board in its sole discretion but in any case a period of not less than 5 fiscal years from the fiscal year in which it is certified by the Oversight Board."],[0,"(c) Development, review, approval, and certification of Fiscal Plans"],[0,"(1) Timing requirement"],[1,"The Governor may not submit to the Legislature a Territory Budget under section 2142 of this title for a fiscal year unless the Oversight Board has certified the Territory Fiscal Plan for that fiscal year in accordance with this subsection, unless the Oversight Board in its sole discretion waives this requirement."],[0,"(2) Fiscal Plan developed by Governor"],[1,"The Governor shall submit to the Oversight Board any proposed Fiscal Plan required by the Oversight Board by the time specified in the notice delivered under subsection (a)."],[0,"(3) Review by the Oversight Board"],[1,"The Oversight Board shall review any proposed Fiscal Plan to determine whether it satisfies the requirements set forth in subsection (b) and, if the Oversight Board determines in its sole discretion that the proposed Fiscal Plan—"],[2,"(A) satisfies such requirements, the Oversight Board shall approve the proposed Fiscal Plan; or"],[2,"(B) does not satisfy such requirements, the Oversight Board shall provide to the Governor—"],[3,"(i) a notice of violation that includes recommendations for revisions to the applicable Fiscal Plan; and"],[3,"(ii) an opportunity to correct the violation in accordance with subsection (d)(1)."],[0,"(d) Revised Fiscal Plan"],[0,"(1) In general"],[1,"If the Governor receives a notice of violation under subsection (c)(3), the Governor shall submit to the Oversight Board a revised proposed Fiscal Plan in accordance with subsection (b) by the time specified in the notice delivered under subsection (a). The Governor may submit as many revised Fiscal Plans to the Oversight Board as the schedule established in the notice delivered under subsection (a) permits."],[0,"(2) Development by Oversight Board"],[1,"If the Governor fails to submit to the Oversight Board a Fiscal Plan that the Oversight Board determines in its sole discretion satisfies the requirements set forth in subsection (b) by the time specified in the notice delivered under subsection (a), the Oversight Board shall develop and submit to the Governor and the Legislature a Fiscal Plan that satisfies the requirements set forth in subsection (b)."],[0,"(e) Approval and certification"],[0,"(1) Approval of Fiscal Plan developed by Governor"],[1,"If the Oversight Board approves a Fiscal Plan under subsection (c)(3), it shall deliver a compliance certification for such Fiscal Plan to the Governor and the Legislature."],[0,"(2) Deemed approval of Fiscal Plan developed by Oversight Board"],[1,"If the Oversight Board develops a Fiscal Plan under subsection (d)(2), such Fiscal Plan shall be deemed approved by the Governor, and the Oversight Board shall issue a compliance certification for such Fiscal Plan to the Governor and the Legislature."],[0,"(f) Joint development of Fiscal Plan"],[0,"Notwithstanding any other provision of this section, if the Governor and the Oversight Board jointly develop a Fiscal Plan for the fiscal year that meets the requirements under this section, and that the Governor and the Oversight Board certify that the fiscal plan 1 reflects a consensus between the Governor and the Oversight Board, then such Fiscal Plan shall serve as the Fiscal Plan for the territory or territorial instrumentality for that fiscal year."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/48/2141?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2141. Approval of Fiscal Plans","tname":"Territories and Insular Possessions","by":{"0":"35","1":"5","3":"20"}},{"t":"usc","label":"48 U.S.C. § 2144","url":"https://www.law.cornell.edu/uscode/text/48/2144","stext":{"head":"§2144. Review of activities to ensure compliance with Fiscal Plan","paras":[[0,"(a) Submission of legislative acts to Oversight Board"],[0,"(1) Submission of acts"],[1,"Except to the extent that the Oversight Board may provide otherwise in its bylaws, rules, and procedures, not later than 7 business days after a territorial government duly enacts any law during any fiscal year in which the Oversight Board is in operation, the Governor shall submit the law to the Oversight Board."],[0,"(2) Cost estimate; certification of compliance or noncompliance"],[1,"The Governor shall include with each law submitted to the Oversight Board under paragraph (1) the following:"],[2,"(A) A formal estimate prepared by an appropriate entity of the territorial government with expertise in budgets and financial management of the impact, if any, that the law will have on expenditures and revenues."],[2,"(B) If the appropriate entity described in subparagraph (A) finds that the law is not significantly inconsistent with the Fiscal Plan for the fiscal year, it shall issue a certification of such finding."],[2,"(C) If the appropriate entity described in subparagraph (A) finds that the law is significantly inconsistent with the Fiscal Plan for the fiscal year, it shall issue a certification of such finding, together with the entity's reasons for such finding."],[0,"(3) Notification"],[1,"The Oversight Board shall send a notification to the Governor and the Legislature if—"],[2,"(A) the Governor submits a law to the Oversight Board under this subsection that is not accompanied by the estimate required under paragraph (2)(A);"],[2,"(B) the Governor submits a law to the Oversight Board under this subsection that is not accompanied by either a certification described in paragraph (2)(B) or (2)(C); or"],[2,"(C) the Governor submits a law to the Oversight Board under this subsection that is accompanied by a certification described in paragraph (2)(C) that the law is significantly inconsistent with the Fiscal Plan."],[0,"(4) Opportunity to respond to notification"],[0,"(A) Failure to provide estimate or certification"],[2,"After sending a notification to the Governor and the Legislature under paragraph (3)(A) or (3)(B) with respect to a law, the Oversight Board may direct the Governor to provide the missing estimate or certification (as the case may be), in accordance with such procedures as the Oversight Board may establish."],[0,"(B) Submission of certification of significant inconsistency with Fiscal Plan and Budget"],[2,"In accordance with such procedures as the Oversight Board may establish, after sending a notification to the Governor and Legislature under paragraph (3)(C) that a law is significantly inconsistent with the Fiscal Plan, the Oversight Board shall direct the territorial government to—"],[3,"(i) correct the law to eliminate the inconsistency; or"],[3,"(ii) provide an explanation for the inconsistency that the Oversight Board finds reasonable and appropriate."],[0,"(5) Failure to comply"],[1,"If the territorial government fails to comply with a direction given by the Oversight Board under paragraph (4) with respect to a law, the Oversight Board may take such actions as it considers necessary, consistent with this chapter, to ensure that the enactment or enforcement of the law will not adversely affect the territorial government's compliance with the Fiscal Plan, including preventing the enforcement or application of the law."],[0,"(6) Preliminary review of proposed acts"],[1,"At the request of the Legislature, the Oversight Board may conduct a preliminary review of proposed legislation before the Legislature to determine whether the legislation as proposed would be consistent with the applicable Fiscal Plan under this subtitle,1 except that any such preliminary review shall not be binding on the Oversight Board in reviewing any law subsequently submitted under this subsection."],[0,"(b) Effect of approved Fiscal Plan on contracts, rules, and regulations"],[0,"(1) Transparency in contracting"],[1,"The Oversight Board shall work with a covered territory's office of the comptroller or any functionally equivalent entity to promote compliance with the applicable law of any covered territory that requires agencies and instrumentalities of the territorial government to maintain a registry of all contracts executed, including amendments thereto, and to remit a copy to the office of the comptroller for inclusion in a comprehensive database available to the public. With respect to Puerto Rico, the term \"applicable law\" refers to 2 L.P.R.A. 97, as amended."],[0,"(2) Authority to review certain contracts"],[1,"The Oversight Board may establish policies to require prior Oversight Board approval of certain contracts, including leases and contracts to a governmental entity or government-owned corporations rather than private enterprises that are proposed to be executed by the territorial government, to ensure such proposed contracts promote market competition and are not inconsistent with the approved Fiscal Plan."],[0,"(3) Sense of Congress"],[1,"It is the sense of Congress that any policies established by the Oversight Board pursuant to paragraph (2) should be designed to make the government contracting process more effective, to increase the public's faith in this process, to make appropriate use of the Oversight Board's time and resources, to make the territorial government a facilitator and not a competitor to private enterprise, and to avoid creating any additional bureaucratic obstacles to efficient contracting."],[0,"(4) Authority to review certain rules, regulations, and executive orders"],[1,"The provisions of this paragraph shall apply with respect to a rule, regulation, or executive order proposed to be issued by the Governor (or the head of any department or agency of the territorial government) in the same manner as such provisions apply to a contract."],[0,"(5) Failure to comply"],[1,"If a contract, rule, regulation, or executive order fails to comply with policies established by the Oversight Board under this subsection, the Oversight Board may take such actions as it considers necessary to ensure that such contract, rule, executive order or regulation will not adversely affect the territorial government's compliance with the Fiscal Plan, including by preventing the execution or enforcement of the contract, rule, executive order or regulation."],[0,"(c) Restrictions on budgetary adjustments"],[0,"(1) Submissions of requests to Oversight Board"],[1,"If the Governor submits a request to the Legislature for the reprogramming of any amounts provided in a certified Budget, the Governor shall submit such request to the Oversight Board, which shall analyze whether the proposed reprogramming is significantly inconsistent with the Budget, and submit its analysis to the Legislature as soon as practicable after receiving the request."],[0,"(2) No action permitted until analysis received"],[1,"The Legislature shall not adopt a reprogramming, and no officer or employee of the territorial government may carry out any reprogramming, until the Oversight Board has provided the Legislature with an analysis that certifies such reprogramming will not be inconsistent with the Fiscal Plan and Budget."],[0,"(3) Prohibition on action until Oversight Board is appointed"],[1,"(A) During the period after a territory becomes a covered territory and prior to the appointment of all members and the Chair of the Oversight Board, such covered territory shall not enact new laws that either permit the transfer of any funds or assets outside the ordinary course of business or that are inconsistent with the constitution or laws of the territory as of June 30, 2016, provided that any executive or legislative action authorizing the movement of funds or assets during this time period may be subject to review and rescission by the Oversight Board upon appointment of the Oversight Board's full membership."],[1,"(B) Upon appointment of the Oversight Board's full membership, the Oversight Board may review, and in its sole discretion, rescind, any law that—"],[2,"(i) was enacted during the period between, with respect to Puerto Rico, May 4, 2016; or with respect to any other territory, 45 days prior to the establishment of the Oversight Board for such territory, and the date of appointment of all members and the Chair of the Oversight Board; and"],[2,"(ii) alters pre-existing priorities of creditors in a manner outside the ordinary course of business or inconsistent with the territory's constitution or the laws of the territory as of, in the case of Puerto Rico, May 4, 2016, or with respect to any other territory, 45 days prior to the establishment of the Oversight Board for such territory;"],[1,"but such rescission shall only be to the extent that the law alters such priorities."],[0,"(d) Implementation of Federal programs"],[0,"In taking actions under this chapter, the Oversight Board shall not exercise applicable authorities to impede territorial actions taken to—"],[1,"(1) comply with a court-issued consent decree or injunction, or an administrative order or settlement with a Federal agency, with respect to Federal programs;"],[1,"(2) implement a federally authorized or federally delegated program;"],[1,"(3) implement territorial laws, which are consistent with a certified Fiscal Plan, that execute Federal requirements and standards; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/48/2144?type=usc&year=mostrecent&link-type=html"},"head":"§2144. Review of activities to ensure compliance with Fiscal Plan","tname":"Territories and Insular Possessions","by":{"0":"41","1":"5"}},{"t":"usc","label":"48 U.S.C. § 2148","url":"https://www.law.cornell.edu/uscode/text/48/2148","subs":["(b)(2)"],"by":{"0":"8"}},{"t":"usc","label":"48 U.S.C. § 2164","url":"https://www.law.cornell.edu/uscode/text/48/2164","subs":["(a)"],"by":{"0":"6"}},{"t":"usc","label":"48 U.S.C. § 2166","url":"https://www.law.cornell.edu/uscode/text/48/2166","by":{"0":"17, 33"}},{"t":"usc","label":"48 U.S.C. § 2172","url":"https://www.law.cornell.edu/uscode/text/48/2172","subs":["(a)"],"by":{"0":"6","1":"5"}},{"t":"usc","label":"48 U.S.C. § 2175","url":"https://www.law.cornell.edu/uscode/text/48/2175","by":{"0":"6, 41"}},{"t":"usc","label":"48 U.S.C. § 2194","url":"https://www.law.cornell.edu/uscode/text/48/2194","subs":["(m)"],"by":{"0":"5, 6"}},{"t":"case","label":"Bonet v. Texas Co. (P. R.), Inc.","cite":"308 U.S. 463","y":1940,"id":"scdb/1939-037","sc":1,"by":{"1":"21"}},{"t":"case","label":"Bonet v. Yabucoa Sugar Co.","cite":"306 U.S. 505","y":1939,"id":"scdb/1938-063","sc":1,"sum":"1. A suit against the Treasurer of Puerto Rico to enforce a tax refund can not be maintained unless authorized by Puerto Rican law. Puerto Rico can not be sued without its consent.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16, 24","2":"30, 32","3":"8"}},{"t":"case","label":"Espinal-Dominguez v. Commonwealth of P.R.","cite":"352 F.3d 490","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/352/490/","by":{"1":"28"}},{"t":"case","label":"Examining Bd. of Eng’rs, Architects & Surveyors v. Flores de Otero","cite":"426 U.S. 572","y":1976,"id":"1975/74-1267","sc":1,"sum":"A Puerto Rico statute permits only United States citizens to practice privately as civil engineers. Appellees are alien civil engineers residing in Puerto Rico, one of whom (Flores de Otero) was denied a license under the statute, and the other of whom (Perez Nogueiro) was granted only a conditional license to work for the Commonwealth. Each appellee brought suit for declaratory and injunctive relief against …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4, 17","3":"10"}},{"t":"case","label":"Florida Prepaid Postsecondary Educ. Expense Bd. v. College Sav. Bank","cite":"527 U.S. 627","y":1999,"id":"1998/98-531","sc":1,"op":1,"sum":"The Court reasoned that although the Fourteenth Amendment authorizes Congress to pass \"appropriate legislation\" to protect parties from being deprived of property without due process, this in itself does not permit the abrogation of state sovereign immunity.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Great N. Life Ins. Co. v. Reed","cite":"322 U.S. 47","y":1944,"id":"scdb/1943-130","sc":1,"sum":"(1) The suit was a suit against the State, and not maintainable without its consent. Eleventh Amendment; Smith v. Reeves, 178 U. S. 436. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32","3":"6"}},{"t":"case","label":"Green v. Mansour","cite":"474 U.S. 64","y":1985,"id":"1985/84-6270","sc":1,"sum":"Petitioner recipients of benefits under the federal Aid to Families With Dependent Children (AFDC) program brought class actions in Federal District Court against respondent Director of the Michigan Department of Social Services. They claimed that respondent's policies of prohibiting the deduction of child care costs and requiring the inclusion of stepparents' income for purposes of calculating earned income, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Gromer v. Standard Dredging Co.","cite":"224 U.S. 362","y":1912,"id":"scdb/1911-215","sc":1,"sum":"Qucere: whether § 12 of the act of Legislative Assembly of Porto Rico of March 8,1906, providing that an injunction may issue to prevent collection of illegal tolls, applies to the District Court of the United States for Porto Rico.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Hans v. Louisiana","cite":"134 U.S. 1","y":1890,"id":"scdb/1889-145","sc":1,"sum":"A State cannot, without its consent, be sued’in a Circuit Court of the United States by one of its own citizens, upon a suggestion that the case is one that arises under the Constitution and laws of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"16, 17, 18","2":"32","3":"6"}},{"t":"case","label":"Hess v. Port Auth. Trans-Hudson Corp.","cite":"513 U.S. 30","y":1994,"id":"1994/93-1197","sc":1,"sum":"PATH is not entitled to Eleventh Amendment immunity from suit in federal court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23, 24"}},{"t":"case","label":"Hutto v. Finney","cite":"437 U.S. 678","y":1978,"id":"1977/76-1660","sc":1,"sum":"The Court held that punitive isolation for longer than thirty days in Arkansas prisons constituted cruel and unusual punishment and violated the Constitution. Justice Stevens conceded that isolation in and of itself was not necessarily unconstitutional and may in fact serve an important, legitimate interest in administering a prison.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Kawananakoa v. Polyblank","cite":"205 U.S. 349","y":1907,"id":"scdb/1906-123","sc":1,"sum":"Under Equity Rule 92, where a part of the mortgage premises has been sold to the sovereign power which refuses to waive, its exemption from suit, the court can, all other parties being joined, except the land so conveyed and decree sale.of the balance and enter deficiency judgment for sum remaining dueif proceeds of salé are insufficient to pay the debt.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"19","2":"30, 32","3":"7"}},{"t":"case","label":"Lebron v. National R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"op":3,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"1":"18, 22","2":"28, 30, 31","3":"5, 12, 13"}},{"t":"case","label":"Mt. Healthy City Sch. Dist. Bd. of Educ. v. Doyle","cite":"429 U.S. 274","y":1977,"id":"1976/75-1278","sc":1,"sum":"Writing for a unanimous Court, Justice Rehnquist held that the school district was not entitled to sovereign immunity, which generally extended to the states themselves and to state officials in their official capacities. He reasoned that the board was more akin to a municipal corporation, given its independent power to issue bonds and levy taxes.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Murray v. Wilson Distilling Co.","cite":"213 U.S. 151","y":1909,"id":"scdb/1908-118","sc":1,"sum":"Purchases máde by state officers of supplies for business carried on by the State are made by the State, and suits by the vendors against the state officers carrying on or winding up the business are suits-against the” State and, under the Eleventh Amendment, beyond the jurisdiction of the Federal courts; and so held as to suits against commissioners to wind up the State Liquor Dispensary of South Carolina.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"National Bank v. County of Yankton","cite":"101 U.S. 129","y":1880,"id":"scdb/1879-195","sc":1,"by":{"1":"16, 20"}},{"t":"case","label":"Ngiraingas v. Sanchez","cite":"495 U.S. 182","y":1990,"id":"1989/88-1281","sc":1,"sum":"Neither the Territory of Guam nor its officers acting in their official capacities are \"persons\" under § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 19","2":"32"}},{"t":"case","label":"Owen v. City of Independence","cite":"445 U.S. 622","y":1980,"id":"1979/78-1779","sc":1,"sum":"A municipality has no immunity from liability under § 1983 flowing from its constitutional violations and may not assert the good faith of its officers as a defense to such liability.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Porto Rico v. Rosaly","cite":"227 U.S. 270","y":1913,"id":"scdb/1912-091","sc":1,"op":1,"sum":"The government of Porto Rico cannot be sued without its consent.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"16, 19","2":"30, 31, 32","3":"1, 8, 9"}},{"t":"case","label":"Puerto Rico v. Sanchez Valle","cite":"579 U.S. 59","y":2016,"id":"2015/15-108","sc":1,"op":1,"sum":"The Court held that Puerto Rico and the U.S. federal government are the same sovereign entity for the purpose of the Double Jeopardy Clause.","sumSrc":"Oyez","by":{"1":"2, 3","2":"5, 18, 21, 22","3":"passim"}},{"t":"case","label":"Puerto Rico v. The Shell Co. (P. R.), Ltd.","cite":"302 U.S. 253","y":1937,"id":"scdb/1937-032","sc":1,"sum":"1. The meaning of a particular word as used in a particular instance in a statute is to be arrived at by consideration not only of the word itself, but also of the context, the purposes of the law, and the circumstances under which the word was used.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17","2":"30, 32","3":"1, 9"}},{"t":"case","label":"Puerto Rico Ports Auth. v. Federal Mar. Comm’n","cite":"531 F.3d 868","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/531/868/","by":{"1":"24"}},{"t":"case","label":"Santa Clara Pueblo v. Martinez","cite":"436 U.S. 49","y":1978,"id":"1977/76-682","sc":1,"sum":"Respondents, a female member of the Santa Clara Pueblo and her daughter, brought this action for declaratory and injunctive relief against petitioners, the Pueblo and its Governor, alleging that a Pueblo ordinance that denies tribal membership to the children of female members who marry outside the tribe, but not to similarly situated children of men of that tribe, violates Title I of the Indian Civil Rights Act of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18","2":"29"}},{"t":"case","label":"Torres v. Texas Dep’t of Pub. Safety","cite":"142 S. Ct. 2455","y":2022,"id":"2021/20-603","sc":1,"sum":"By ratifying the Constitution, the States agreed their sovereignty would yield to the national power to raise and support the Armed Forces; Congress may exercise this power to authorize private damages suits against nonconsenting States, as in the Uniformed Services Employment and Reemployment Rights Act of 1994.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20","2":"19"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"18"}},{"t":"const","label":"Article IV, Section 3, Clause 2","clauses":[["property-clause","Territory and Property Clause"]],"text":"The Congress shall have Power to dispose of and make all needful Rules and Regulations respecting the Territory or other Property belonging to the United States; and nothing in this Constitution shall be so construed as to Prejudice any Claims of the United States, or of any particular State.","by":{"1":"4, 20, 23","2":"passim"}},{"t":"const","label":"Amendment XI","clauses":[["eleventh-amendment","Eleventh Amendment"]],"text":"The Judicial power of the United States shall not be construed to extend to any suit in law or equity, commenced or prosecuted against one of the United States by Citizens of another State, or by Citizens or Subjects of any Foreign State.","by":{"1":"passim","2":"passim"}},{"t":"const","label":"Amendment XIV, Section 5","clauses":[["enforcement-14","Enforcement Clause (Section 5)"]],"text":"The Congress shall have power to enforce, by appropriate legislation, the provisions of this article.","by":{"1":"12, 20"}},{"t":"law","label":"Pub. L. No. 87-189","url":"https://www.govinfo.gov/link/statute/75/417","by":{"1":"21"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","subs":["(a)","(b)"],"stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"1":"13, 28, 28, 28"}},{"t":"usc","label":"25 U.S.C. § 2701","url":"https://www.law.cornell.edu/uscode/text/25/2701","by":{"1":"26","2":"34, 40"}},{"t":"usc","label":"48 U.S.C. § 2101","url":"https://www.law.cornell.edu/uscode/text/48/2101","stext":{"head":"§2101. Effective date","paras":[[0,"(a) In general"],[0,"Except as provided in subsection (b), this chapter shall take effect on June 30, 2016."],[0,"(b) Subchapter III and Subchapter VI"],[0,"(1) Subchapter III shall apply with respect to cases commenced under subchapter III on or after June 30, 2016."],[0,"(2) Subchapters III and VI shall apply with respect to debts, claims, and liens (as such terms are defined in section 101 of title 11) created before, on, or after such date."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/48/2101?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2101. Effective date","tname":"Territories and Insular Possessions","by":{"1":"1, 4","2":"passim"}},{"t":"usc","label":"48 U.S.C. § 2106","url":"https://www.law.cornell.edu/uscode/text/48/2106","by":{"1":"29"}},{"t":"usc","label":"48 U.S.C. § 2142","url":"https://www.law.cornell.edu/uscode/text/48/2142","by":{"1":"5","3":"20"}},{"t":"usc","label":"48 U.S.C. § 2143","url":"https://www.law.cornell.edu/uscode/text/48/2143","by":{"1":"5"}},{"t":"usc","label":"48 U.S.C. § 2147","url":"https://www.law.cornell.edu/uscode/text/48/2147","by":{"1":"5"}},{"t":"usc","label":"48 U.S.C. § 2161","url":"https://www.law.cornell.edu/uscode/text/48/2161","subs":["(a)"],"stext":{"head":"§2161. Applicability of other laws; definitions","paras":[[0,"(a) Sections applicable to cases under this subchapter"],[0,"Sections 101 (except as otherwise provided in this section), 102, 104, 105, 106, 107, 108, 112, 333, 344, 347(b), 349, 350(b), 351, 361, 362, 364(c), 364(d), 364(e), 364(f), 365, 366, 501, 502, 503, 504, 506, 507(a)(2), 509, 510, 524(a)(1), 524(a)(2), 544, 545, 546, 547, 548, 549(a), 549(c), 549(d), 550, 551, 552, 553, 555, 556, 557, 559, 560, 561, 562, 902 (except as otherwise provided in this section), 922, 923, 924, 925, 926, 927, 928, 942, 944, 945, 946, 1102, 1103, 1109, 1111(b), 1122, 1123(a)(1), 1123(a)(2), 1123(a)(3), 1123(a)(4), 1123(a)(5), 1123(b), 1123(d), 1124, 1125, 1126(a), 1126(b), 1126(c), 1126(e), 1126(f), 1126(g), 1127(d), 1128, 1129(a)(2), 1129(a)(3), 1129(a)(6), 1129(a)(8), 1129(a)(10), 1129(b)(1), 1129(b)(2)(A), 1129(b)(2)(B), 1142(b), 1143, 1144, 1145, and 1146(a) of title 11 apply in a case under this subchapter and section 930 of title 11 applies in a case under this subchapter; however, section 930 shall not apply in any case during the first 120 days after the date on which such case is commenced under this subchapter."],[0,"(b) Meanings of terms"],[0,"A term used in a section of title 11, made applicable in a case under this subchapter by subsection (a), has the meaning given to the term for the purpose of the applicable section, unless the term is otherwise defined in this subchapter."],[0,"(c) Definitions"],[0,"In this subchapter:"],[0,"(1) Affiliate"],[1,"The term \"affiliate\" means, in addition to the definition made applicable in a case under this subchapter by subsection (a)—"],[2,"(A) for a territory, any territorial instrumentality; and"],[2,"(B) for a territorial instrumentality, the governing territory and any of the other territorial instrumentalities of the territory."],[0,"(2) Debtor"],[1,"The term \"debtor\" means the territory or covered territorial instrumentality concerning which a case under this subchapter has been commenced."],[0,"(3) Holder of a claim or interest"],[1,"The term \"holder of a claim or interest\", when used in section 1126 of title 11, made applicable in a case under this subchapter by subsection (a)—"],[2,"(A) shall exclude any Issuer or Authorized Instrumentality of the Territory Government Issuer (as defined under subchapter VI of this chapter) or a corporation, trust or other legal entity that is controlled by the Issuer or an Authorized Territorial Instrumentality of the Territory Government Issuer, provided that the beneficiaries of such claims, to the extent they are not referenced in this subparagraph, shall not be excluded, and that, for each excluded trust or other legal entity, the court shall, upon the request of any participant or beneficiary of such trust or entity, at any time after the commencement of the case, order the appointment of a separate committee of creditors pursuant to section 1102(a)(2) of title 11; and"],[2,"(B) with reference to Insured Bonds, shall mean the monoline insurer insuring such Insured Bond to the extent such insurer is granted the right to vote Insured Bonds for purposes of directing remedies or consenting to proposed amendments or modifications as provided in the applicable documents pursuant to which such Insured Bond was issued and insured."],[0,"(4) Insured Bond"],[1,"The term \"Insured Bond\" means a bond subject to a financial guarantee or similar insurance contract, policy and/or surety issued by a monoline insurer."],[0,"(5) Property of the estate"],[1,"The term \"property of the estate\", when used in a section of title 11 made applicable in a case under this subchapter by subsection (a), means property of the debtor."],[0,"(6) State"],[1,"The term \"State\" 1 when used in a section of title 11 made applicable in a case under this subchapter by subsection (a) 1 means State or territory when used in reference to the relationship of a State to the municipality of the State or the territorial instrumentality of a territory, as applicable."],[0,"(7) Trustee"],[1,"The term \"trustee\", when used in a section of title 11 made applicable in a case under this subchapter by subsection (a), means the Oversight Board, except as provided in section 926 of title 11. The term \"trustee\" as described in this paragraph does not mean the U.S. Trustee, an official of the United States Trustee Program, which is a component of the United States Department of Justice."],[0,"(d) Reference to subchapter"],[0,"Solely for purposes of this subchapter, a reference to \"this title\", \"this chapter\", or words of similar import in a section of title 11 made applicable in a case under this subchapter by subsection (a) or to \"this title\", \"title 11\", \"Chapter 9\", \"Chapter 11\", \"the Code\", or words of similar import in the Federal Rules of Bankruptcy Procedure made applicable in a case under this subchapter shall be deemed to be a reference to this subchapter."],[0,"(e) Substantially similar"],[0,"In determining whether claims are \"substantially similar\" for the purpose of section 1122 of title 11, made applicable in a case under this subchapter by subsection (a), the Oversight Board shall consider whether such claims are secured and whether such claims have priority over other claims."],[0,"(f) Operative clauses"],[0,"A section made applicable in a case under this subchapter by subsection (a) that is operative if the business of the debtor is authorized to be operated is operative in a case under this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/48/2161?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2161. Applicability of other laws; definitions","tname":"Territories and Insular Possessions","by":{"1":"5, 31","3":"20"}},{"t":"usc","label":"11 U.S.C. § 106","url":"https://www.law.cornell.edu/uscode/text/11/106","stext":{"head":"§106. Waiver of sovereign immunity","paras":[[0,"(a) Notwithstanding an assertion of sovereign immunity, sovereign immunity is abrogated as to a governmental unit to the extent set forth in this section with respect to the following:"],[1,"(1) Sections 105, 106, 107, 108, 303, 346, 362, 363, 364, 365, 366, 502, 503, 505, 506, 510, 522, 523, 524, 525, 542, 543, 544, 545, 546, 547, 548, 549, 550, 551, 552, 553, 722, 724, 726, 744, 749, 764, 901, 922, 926, 928, 929, 944, 1107, 1141, 1142, 1143, 1146, 1201, 1203, 1205, 1206, 1227, 1231, 1301, 1303, 1305, and 1327 of this title."],[1,"(2) The court may hear and determine any issue arising with respect to the application of such sections to governmental units."],[1,"(3) The court may issue against a governmental unit an order, process, or judgment under such sections or the Federal Rules of Bankruptcy Procedure, including an order or judgment awarding a money recovery, but not including an award of punitive damages. Such order or judgment for costs or fees under this title or the Federal Rules of Bankruptcy Procedure against any governmental unit shall be consistent with the provisions and limitations of section 2412(d)(2)(A) of title 28."],[1,"(4) The enforcement of any such order, process, or judgment against any governmental unit shall be consistent with appropriate nonbankruptcy law applicable to such governmental unit and, in the case of a money judgment against the United States, shall be paid as if it is a judgment rendered by a district court of the United States."],[1,"(5) Nothing in this section shall create any substantive claim for relief or cause of action not otherwise existing under this title, the Federal Rules of Bankruptcy Procedure, or nonbankruptcy law."],[0,"(b) A governmental unit that has filed a proof of claim in the case is deemed to have waived sovereign immunity with respect to a claim against such governmental unit that is property of the estate and that arose out of the same transaction or occurrence out of which the claim of such governmental unit arose."],[0,"(c) Notwithstanding any assertion of sovereign immunity by a governmental unit, there shall be offset against a claim or interest of a governmental unit any claim against such governmental unit that is property of the estate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/106?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§106. Waiver of sovereign immunity","tname":"Bankruptcy","by":{"1":"31","3":"20"}},{"t":"usc","label":"35 U.S.C. § 296","url":"https://www.law.cornell.edu/uscode/text/35/296","subs":["(a)"],"stext":{"head":"§296. Liability of States, instrumentalities of States, and State officials for infringement of patents","paras":[[0,"(a) In General.—Any State, any instrumentality of a State, and any officer or employee of a State or instrumentality of a State acting in his official capacity, shall not be immune, under the eleventh amendment of the Constitution of the United States or under any other doctrine of sovereign immunity, from suit in Federal court by any person, including any governmental or nongovernmental entity, for infringement of a patent under section 271, or for any other violation under this title."],[0,"(b) Remedies.—In a suit described in subsection (a) for a violation described in that subsection, remedies (including remedies both at law and in equity) are available for the violation to the same extent as such remedies are available for such a violation in a suit against any private entity. Such remedies include damages, interest, costs, and treble damages under section 284, attorney fees under section 285, and the additional remedy for infringement of design patents under section 289."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/296?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§296. Liability of States, instrumentalities of States, and State officials for infringement of patents","tname":"Patents","by":{"1":"26"}},{"t":"case","label":"Bhatia Gautier v. Rosselló Nevares","cite":"199 P.R. Dec. 59","y":2017,"court":"P.R.","url":"https://www.courtlistener.com/c/P.R.%20Dec./199/59/","by":{"2":"9, 10, 46, 47"}},{"t":"case","label":"Branch v. Smith","cite":"538 U.S. 254","y":2003,"id":"2002/01-1437","sc":1,"sum":"The Court held, 9-0, that the District Court properly enjoined enforcement of the state- court plan that lacked the required timely preclearance.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Calero-Toledo v. Pearson Yacht Leasing Co.","cite":"416 U.S. 663","y":1974,"id":"1973/73-157","sc":1,"sum":"A pleasure yacht, which appellee had leased to Puerto Rican residents, was seized, pursuant to Puerto Rican statutes providing for forfeiture of vessels used for unlawful purposes, without prior notice to appellee or the lessees and without a prior adversary hearing, after authorities had discovered marihuana aboard her. Appellee was neither involved in nor aware of a lessee's wrongful use of the yacht. Appellee …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5","3":"10"}},{"t":"case","label":"Coffield v. Territory of Hawaii","cite":"13 Haw. 478","y":1901,"url":"https://www.courtlistener.com/c/Haw./13/478/","by":{"2":"30"}},{"t":"case","label":"Figueroa Ferrer v. E.L.A.","cite":"7 P.R. Offic. Trans. 278","y":1978,"court":"P.R.","url":"https://www.courtlistener.com/c/P.R.%20Offic.%20Trans./7/278/","by":{"2":"10, 46"}},{"t":"case","label":"France v. Connor","cite":"161 U.S. 65","y":1896,"id":"scdb/1895-112","sc":1,"ar":1,"sum":"Section 18 of the act of Congress of March 3, 1887, c. 397, conferring and regulating the right of dower, applies to the Territory of Utah only, and not to other Territories of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"27","3":"14"}},{"t":"case","label":"Franchise Tax Bd. of Cal. v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"op":1,"sum":"Nevada v. Hall, 440 U. S. 410, is overruled; States retain their sovereign immunity from private suits brought in courts of other States.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"18, 19, 30, 32","3":"4, 6, 12"}},{"t":"case","label":"Grafton v. United States","cite":"206 U.S. 333","y":1907,"id":"scdb/1906-085","sc":1,"sum":"The prohibition of double jeopardy is applicable to all criminal prosecutions in the Philippine Islands.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"sum":"In addition to emphasizing Missouri's, or any other state's, Tenth Amendment right to define the qualifications of its highest state officials, the Court held that the regulations of the ADEA did not apply to \"policy-making\" appointees such as state court judges.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Hutto v. S.C. Ret. Sys.","cite":"773 F.3d 536","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/773/536/","by":{"2":"23"}},{"t":"case","label":"Inter-Island Steam Nav. Co. v. Territory of Hawaii","cite":"305 U.S. 306","y":1938,"id":"scdb/1938-002","sc":1,"sum":"1. The conclusion of the Supreme Court of Hawaii that a common carrier of freight and passengers by water between different points in the Territory was a public utility within the meaning of the Hawaii Utilities Act of 1913, is accepted by this Court on review.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27","3":"14"}},{"t":"case","label":"Jinks v. Richland County","cite":"538 U.S. 456","y":2003,"id":"2002/02-258","sc":1,"ar":1,"sum":"The Court held that section 1367(d)'s application to claims brought against a State's political subdivisions is constitutional.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Jusino Mercado v. Puerto Rico","cite":"214 F.3d 34","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/214/34/","by":{"2":"33"}},{"t":"case","label":"Kiowa Tribe of Okla. v. Mfg. Techs., Inc.","cite":"523 U.S. 751","y":1998,"id":"1997/96-1037","sc":1,"sum":"The Court held that Indian tribes enjoy sovereign immunity from civil suits on contracts, whether those contracts involve governmental or commercial activities and whether they were made on or off a reservation.","sumSrc":"Oyez","by":{"2":"28, 30, 32"}},{"t":"case","label":"Late Corp. of the Church of Jesus Christ of Latter- Day Saints v. United States","cite":"136 U.S. 1","y":1890,"id":"scdb/1889-258","sc":1,"sum":"-Decided May 19, 1890.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Murphy v. Ramsey","cite":"114 U.S. 15","y":1885,"id":"scdb/1884-173","sc":1,"sum":"The Board of Commissioners appointed for the Territory of Utah in pursuance of § 9 of the act of Congress approved March 22, 1882, entitled “ An act to amend § 5352 of the Revised, Statutes of the United States in reference to bigamy, and for other purposes,” 22 Stat. 30, have no power over the registration of voters or the c'onduet of elections. Their authority is limited to the appointment of registration and …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Ortiz v. Bauermeister","cite":"152 P.R. Dec. 161","y":2000,"court":"P.R.","url":"https://www.courtlistener.com/c/P.R.%20Dec./152/161/","by":{"2":"10, 46"}},{"t":"case","label":"PennEast Pipeline Co. v. New Jersey","cite":"141 S. Ct. 2244","y":2021,"id":"2020/19-1039","sc":1,"sum":"A certificate of public convenience and necessity issued by the Federal Energy Regulatory Commission pursuant to §717f(h) of the Natural Gas Act authorizes a private company to condemn all necessary rights-of-way, whether owned by private parties or States.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"17","3":"7"}},{"t":"case","label":"People of Porto Rico v. Ramos","cite":"232 U.S. 627","y":1914,"id":"scdb/1913-200","sc":1,"sum":"Immunity of sovereignty from suit without consent does not permit the sovereign to reverse the action invoked by it so that it may come in and go out of court at will without the right of the other party to resist either step.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"29, 30","3":"9"}},{"t":"case","label":"R&D Master Enters. v. Fin. Oversight & Mgmt. Bd.","cite":"2022 WL 1092697","y":2022,"court":"D.P.R. Apr. 12","by":{"2":"43"}},{"t":"case","label":"Rodríguez v. P.R. Fed. Affs. Admin.","cite":"435 F.3d 378","y":2006,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/435/378/","by":{"2":"33"}},{"t":"case","label":"Rodríguez v. Popular Democratic Party","cite":"457 U.S. 1","y":1982,"id":"1981/81-328","sc":1,"sum":"The Court, in a unanimous opinion, began by noting that the Constitution does not compel a fixed method of selecting state or local representatives. As such, the Puerto Rican Commonwealth legislature could vest exclusive interim appointment power in parties affiliated with the previous incumbent.","sumSrc":"Oyez","by":{"2":"20","3":"1, 10"}},{"t":"case","label":"Shively v. Bowlby","cite":"152 U.S. 1","y":1894,"id":"scdb/1893-140","sc":1,"sum":"This court has jurisdiction to review by writ of.error a judgment of the highest court of the State of Oregon, deciding that a donation land claim under the act of Congress of September 27, 1850, c. 76, of land bounded by tide water, passed no title or right below high water mark, as against a subsequent grant from the State.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Simms v. Simms","cite":"175 U.S. 162","y":1899,"id":"scdb/1899-012","sc":1,"sum":"No appeal lies to this court from a decree of the Supreme Court of a Territory granting or refusing a divorce.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Territory of Wisconsin v. Doty","cite":"1 Pin. 396","y":1844,"court":"Wis.","url":"https://www.courtlistener.com/c/Pin./1/396/","by":{"2":"30"}},{"t":"case","label":"U.S. Dep’t of Energy v. Ohio","cite":"503 U.S. 607","y":1992,"id":"1991/90-1341","sc":1,"sum":"Congress has not waived the National Government's sovereign immunity from liability for civil fines imposed by a State for past violations of the CWA or RCRA.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"United States v. Lara","cite":"541 U.S. 193","y":2004,"id":"2003/03-107","sc":1,"sum":"In an opinion written by Justice Stephen G. Breyer and joined by Chief Justice Rehnquist and three other Justices, the Court found that the right to prosecute nonmember Indians is inherent in the sovereignty of Native American tribes.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"United States v. Vaello Madero","cite":"142 S. Ct. 1539","y":2022,"id":"2021/20-303","sc":1,"sum":"The Constitution does not require Congress to make Supplemental Security Income benefits available to residents of Puerto Rico.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"5"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"2":"19"}},{"t":"const","label":"Amendment XXI","text":"The eighteenth article of amendment to the Constitution of the United States is hereby repealed. The transportation or importation into any State, Territory, or possession of the United States for delivery or use therein of intoxicating liquors, in violation of the laws thereof, is hereby prohibited. This article shall be inoperative unless it shall have been ratified as an amendment to the Constitution by conventions in the several States, as provided in the Constitution, within seven years from the date of the submission hereof to the States by the Congress.","by":{"2":"20"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§101. Definitions","tname":"Bankruptcy","by":{"2":"8"}},{"t":"usc","label":"29 U.S.C. § 203","url":"https://www.law.cornell.edu/uscode/text/29/203","subs":["(x)"],"by":{"2":"35"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","by":{"2":"34, 35"}},{"t":"usc","label":"48 U.S.C. § 731","url":"https://www.law.cornell.edu/uscode/text/48/731","by":{"2":"5, 33"}},{"t":"const","label":"Article II, Section 4","clauses":[["impeachment","Impeachment"]],"text":"The President, Vice President and all civil Officers of the United States, shall be removed from Office on Impeachment for, and Conviction of, Treason, Bribery, or other high Crimes and Misdemeanors.","by":{"2":"9, 11"}},{"t":"const","label":"Article II, Section 8","by":{"2":"46"}},{"t":"case","label":"Asociación Puertorriqueña De Profesores Universitarios v. Univ. of P.R.","cite":"632 B.R. 1","y":2021,"court":"D.P.R.","url":"https://www.courtlistener.com/c/B.R./632/1/","by":{"3":"19"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"Idaho v. Coeur d’Alene Tribe of Idaho","cite":"521 U.S. 261","y":1997,"id":"1996/94-1474","sc":1,"sum":"Authored by Justice Anthony Kennedy, the Court ruled that the Coeur d'Alene Tribe's suit against the state officials may not proceed in federal court because States enjoy Eleventh Amendment immunity in suits filed by Indian tribes.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Iowa Mut. Ins. Co. v. LaPlante","cite":"480 U.S. 9","y":1987,"id":"1986/85-1589","sc":1,"sum":"Respondent employee (hereafter respondent) of a ranch located on the Blackfeet Indian Reservation and owned by Indians, brought suit in Blackfeet Tribal Court seeking compensation from the ranch for personal injuries respondent suffered when the cattle truck he was driving \"jackknifed,\" and seeking compensatory and punitive damages from petitioner, the ranch's insurer, for its alleged bad-faith refusal to settle the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"13"}},{"t":"case","label":"Memphis & C. R.R. Co. v. Tennessee","cite":"101 U.S. 337","y":1880,"id":"scdb/1879-152","sc":1,"sum":"The facts\"' are stated in the opinion of the court.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"Nevada v. Hall","cite":"440 U.S. 410","y":1979,"id":"1978/77-1337","sc":1,"op":1,"sum":"A State is not constitutionally immune from suit in the courts of another State.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"12"}},{"t":"case","label":"Okla. Tax Comm’n v. Citizen Band Potawatomi Indian Tribe","cite":"498 U.S. 505","y":1991,"id":"1990/89-1322","sc":1,"sum":"Under the doctrine of tribal sovereign immunity, a State that has not asserted jurisdiction over Indian lands under Public Law 280 may not tax sales of goods to tribesmen occurring on land held in trust for a federally recognized Indian tribe, but is free to collect taxes on such sales to nonmembers of the tribe.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"Porto Rico v. Emmanuel","cite":"235 U.S. 251","y":1914,"id":"scdb/1914-016","sc":1,"sum":"Under § 35 of the Foraker Act of April 12, 1900, the jurisdiction of this court on appeals from the District Court of the United States for Porto Rico is confined to determining whether.the facfy 'found by that court support its judgment and whether there was material and prejudicial error in the admission or rejection of evidence manifested by exceptions properly certified.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"9"}},{"t":"case","label":"Three Affiliated Tribes of Fort Berthold Res. v. Wold Eng’g, P.C.","cite":"476 U.S. 877","y":1986,"id":"1985/84-1973","sc":1,"sum":"Petitioner Indian tribe brought suit against respondent corporation (hereafter respondent) in a North Dakota state court for negligence and breach of contract in connection with respondent's construction of a water-supply system on petitioner's reservation. The trial court dismissed the suit for lack of jurisdiction. The North Dakota Supreme Court held that a North Dakota statute (Chapter 27-19)-which provides that …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5, 12"}},{"t":"case","label":"United States v. Lee","cite":"106 U.S. 196","y":1882,"id":"scdb/1882-052","sc":1,"sum":"Noting that common-law immunity applies in “any judicial tribunal”.","sumSrc":"brief:3","by":{"3":"4"}},{"t":"case","label":"UTIER v. Ortiz Vazquez","cite":"435 F. Supp. 3d 377","y":2020,"court":"D.P.R.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/435/377/","by":{"3":"19"}},{"t":"usc","label":"20 U.S.C. § 1403","url":"https://www.law.cornell.edu/uscode/text/20/1403","subs":["(a)"],"by":{"3":"21"}},{"t":"usc","label":"42 U.S.C. § 2000d-7","url":"https://www.law.cornell.edu/uscode/text/42/2000d-7","subs":["(a)(1)"],"by":{"3":"21"}}]};